-- ============================================================================
--  UniGuard · 053 · Official barangay boundaries for report routing
--
--  PROBLEM
--    Reports were routed with barangay_geoms (migration 030): APPROXIMATE
--    centre points + boxes. Checked against the official boundaries several
--    centres were kilometres off (some in the sea), so e.g. reports from the
--    northern part of Poblacion (Narciso Ramos Sports Center, Pangasinan
--    National High School) were filed under Bantayan. The "inside Lingayen"
--    box was also too small: parts of Estanza, Malawa, Rosario, Lasip,
--    Sabangan and Wawa were rejected as "outside Lingayen".
--
--  DATA
--    PSA barangay boundaries, PSGC 3Q 2026, high resolution, from
--    github.com/faeldon/philippines-json-maps release v1.0.0 (MIT),
--    file geojson/municities/hires/bgysubmuns-municity-105522000.0.1.json
--    (Lingayen, PSGC 105522000). geojson-hires.zip SHA-256 starts
--    ca9bf64c2550d028 and matched the release's SHA256SUMS.
--    All 32 barangays, names identical to the app's list, single polygons,
--    geom_src = 'source', no overlaps (checked on a ~50 m grid).
--    Coordinates are stored at full source precision as arrays.
--
--  WHY NOT THE BUILT-IN polygon TYPE
--    PostgreSQL's geometric operators (polygon @> point) compare with a fuzzy
--    tolerance and misplaced ~2.6% of test points inside the wrong barangay.
--    Containment is therefore an exact ray-casting test (ug_point_in_ring),
--    the same algorithm used to check the data.
--
--  CHANGES
--    · barangay_boundaries: one ring per barangay (lngs[], lats[]) + box.
--    · resolve_barangay(): the barangay whose boundary contains the point;
--      outside every boundary (shoreline, river mouth, a point just past the
--      municipal line) the nearest boundary. barangay_geoms is used only if
--      no boundaries are loaded.
--    · barangay_geoms centroids / boxes replaced with values computed from the
--      official boundaries, so the fallback is accurate too.
--    · lingayen_bounds(): widened to the real municipal extent
--      (lat 15.9344–16.0490, lng 120.1425–120.2915) plus a margin, keeping
--      the sea to the north for coastal reports. js/geo.js BOUNDS matches.
--    · barangay_at(lat, lng): lets the app show the exact barangay the
--      server will assign before the report is sent.
--    · re-runs reroute_misrouted_reports() (migration 052): reports still in
--      'reported' move to the right barangay; verified/dispatched ones are
--      only counted (held_for_review), never moved.
--
--  Additive + idempotent. Begin/commit so it applies atomically.
--  Requires 052 (reroute_misrouted_reports).
-- ============================================================================

begin;

-- ------------------------------------------------------------ the boundaries
create table if not exists public.barangay_boundaries (
  barangay_id uuid primary key references public.barangays(id) on delete cascade,
  psgc        bigint,
  lngs        double precision[] not null,
  lats        double precision[] not null,
  min_lat     double precision not null,
  max_lat     double precision not null,
  min_lng     double precision not null,
  max_lng     double precision not null,
  source      text not null default '',
  updated_at  timestamptz not null default now(),
  constraint barangay_boundaries_ring_check
    check (array_length(lngs, 1) >= 3 and array_length(lngs, 1) = array_length(lats, 1))
);

alter table public.barangay_boundaries enable row level security;

-- public geography: anyone signed in may read; writes only from the backend
drop policy if exists barangay_boundaries_read on public.barangay_boundaries;
create policy barangay_boundaries_read on public.barangay_boundaries
  for select to authenticated using (true);

revoke insert, update, delete on public.barangay_boundaries from anon, authenticated;
grant select on public.barangay_boundaries to authenticated;

