ensured as (
  insert into public.barangays (name)
  select v.name from v
  on conflict (name) do nothing
  returning id, name
),
ids as (
  select v.*, coalesce(b.id, e.id) as barangay_id
    from v
    left join public.barangays b on b.name = v.name
    left join ensured e on e.name = v.name
),
shapes as (
  -- data-modifying CTE: always runs, whether or not it is referenced
  insert into public.barangay_boundaries
    (barangay_id, psgc, lngs, lats, min_lat, max_lat, min_lng, max_lng, source, updated_at)
  select barangay_id, psgc, lngs::double precision[], lats::double precision[],
         min_lat, max_lat, min_lng, max_lng,
         'PSA PSGC 3Q 2026 (faeldon/philippines-json-maps v1.0.0, hires)', now()
    from ids
  on conflict (barangay_id) do update
     set psgc = excluded.psgc, lngs = excluded.lngs, lats = excluded.lats,
         min_lat = excluded.min_lat, max_lat = excluded.max_lat,
         min_lng = excluded.min_lng, max_lng = excluded.max_lng,
         source = excluded.source, updated_at = now()
)
-- the fallback table gets the official centroids + boxes as well
insert into public.barangay_geoms (barangay_id, centroid_lat, centroid_lng, min_lat, max_lat, min_lng, max_lng, source, updated_at)
select barangay_id, c_lat, c_lng, min_lat, max_lat, min_lng, max_lng,
       'centroid/box of PSA boundary (migration 053)', now()
  from ids
on conflict (barangay_id) do update
   set centroid_lat = excluded.centroid_lat, centroid_lng = excluded.centroid_lng,
       min_lat = excluded.min_lat, max_lat = excluded.max_lat,
       min_lng = excluded.min_lng, max_lng = excluded.max_lng,
       source = excluded.source, updated_at = now();

-- ------------------------------------------------------------ geometry helpers
-- exact ray casting: is (x = lng, y = lat) inside the ring?
create or replace function public.ug_point_in_ring(
  p_x double precision, p_y double precision,
  p_xs double precision[], p_ys double precision[])
returns boolean language plpgsql immutable as $$
declare
  n int := array_length(p_xs, 1);
  i int;
  j int;
  c boolean := false;
begin
  if n is null or n < 3 then
    return false;
  end if;
  j := n;
  for i in 1..n loop
    if ((p_ys[i] > p_y) <> (p_ys[j] > p_y))
       and (p_x < (p_xs[j] - p_xs[i]) * (p_y - p_ys[i]) / (p_ys[j] - p_ys[i]) + p_xs[i]) then
      c := not c;
    end if;
    j := i;
  end loop;
  return c;
end;
$$;

-- metres from (lat, lng) to the nearest edge of the ring (local flat projection,
-- exact enough at municipal scale)
create or replace function public.ug_distance_to_ring_m(
  p_lat double precision, p_lng double precision,
  p_xs double precision[], p_ys double precision[])
returns double precision language plpgsql immutable as $$
declare
  n    int := array_length(p_xs, 1);
  k    double precision := cos(radians(p_lat));
  i    int;
  j    int;
  ax double precision; ay double precision;
  bx double precision; by_ double precision;
  dx double precision; dy double precision;
  t  double precision;
  d  double precision;
  best double precision := 'infinity';
begin
  if n is null or n < 2 then
    return null;
  end if;
  j := n;
  for i in 1..n loop
    ax := (p_xs[j] - p_lng) * k;  ay := p_ys[j] - p_lat;
    bx := (p_xs[i] - p_lng) * k;  by_ := p_ys[i] - p_lat;
    dx := bx - ax;  dy := by_ - ay;
    if dx = 0 and dy = 0 then
      t := 0;
    else
      t := greatest(0, least(1, -(ax * dx + ay * dy) / (dx * dx + dy * dy)));
    end if;
    d := sqrt((ax + t * dx) ^ 2 + (ay + t * dy) ^ 2);
    if d < best then
      best := d;
    end if;
    j := i;
  end loop;
  return best * 111320.0;
end;
$$;

-- ------------------------------------------------------------ service area
-- Real municipal extent lat 15.9344–16.0490, lng 120.1425–120.2915, plus
-- ~1 km to the south/west/east and the existing sea margin to the north.
-- Keep in sync with js/geo.js BOUNDS.
create or replace function public.lingayen_bounds()
returns table (min_lat double precision, max_lat double precision, min_lng double precision, max_lng double precision)
language sql immutable as $$
  select 15.925::double precision, 16.085::double precision, 120.135::double precision, 120.30::double precision;
$$;

-- ------------------------------------------------------------ routing
create or replace function public.resolve_barangay(p_lat double precision, p_lng double precision)
returns uuid language plpgsql stable security definer set search_path = public as $$
declare
  v_id uuid;
begin
  perform public.validate_report_coords(p_lat, p_lng);

  if exists (select 1 from public.barangay_boundaries) then
    -- inside an official boundary (boundaries do not overlap)
    select b.barangay_id into v_id
      from public.barangay_boundaries b
     where p_lat between b.min_lat and b.max_lat
       and p_lng between b.min_lng and b.max_lng
       and public.ug_point_in_ring(p_lng, p_lat, b.lngs, b.lats)
     order by b.psgc
     limit 1;
    if v_id is not null then
      return v_id;
    end if;
    -- outside every boundary (shoreline, river, just past the line): nearest
    select b.barangay_id into v_id
      from public.barangay_boundaries b
     order by public.ug_distance_to_ring_m(p_lat, p_lng, b.lngs, b.lats), b.psgc
     limit 1;
    return v_id;
  end if;

  -- no boundaries loaded: centroid fallback (051 behaviour)
  select g.barangay_id into v_id
    from public.barangay_geoms g
   where p_lat between g.min_lat and g.max_lat
     and p_lng between g.min_lng and g.max_lng
   order by public.distance_m(p_lat, p_lng, g.centroid_lat, g.centroid_lng)
   limit 1;
  if v_id is not null then
    return v_id;
  end if;
  select g.barangay_id into v_id
    from public.barangay_geoms g
   order by public.distance_m(p_lat, p_lng, g.centroid_lat, g.centroid_lng)
   limit 1;
  return v_id;
end;
$$;

-- ------------------------------------------------- what the server will assign
-- The report form calls this after GPS / pin / typed coordinates so the
-- citizen sees the barangay the report will actually be filed under.
create or replace function public.barangay_at(p_lat double precision, p_lng double precision)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_id     uuid;
  v_name   text;
  v_inside boolean := false;
begin
  begin
    v_id := public.resolve_barangay(p_lat, p_lng);
  exception when others then
    return jsonb_build_object('ok', false, 'error', sqlerrm);
  end;
  select name into v_name from public.barangays where id = v_id;
  select coalesce(bool_or(public.ug_point_in_ring(p_lng, p_lat, b.lngs, b.lats)), false)
    into v_inside
    from public.barangay_boundaries b
   where b.barangay_id = v_id;
  return jsonb_build_object('ok', v_id is not null, 'id', v_id, 'name', v_name, 'inside', v_inside);
end;
$$;

revoke all on function public.barangay_at(double precision, double precision) from public, anon;
grant execute on function public.barangay_at(double precision, double precision) to authenticated;

-- ------------------------------------------------- fix reports nobody acted on
select public.reroute_misrouted_reports() as reroute_result;

commit;
